	"banks_point_5": "\u05E2\u05DE\u05DC\u05D5\u05EA \u05DE\u05E9\u05EA\u05E0\u05D5\u05EA \u05D5\u05E7\u05E0\u05E1\u05D5\u05EA",
	"banks_point_6": "\u05DE\u05D0\u05E4\u05E9\u05E8\u05D9\u05DD \u05DE\u05E9\u05D9\u05DB\u05EA \u05D9\u05EA\u05E8 \u05E2\u05DD \u05E2\u05DE\u05DC\u05D5\u05EA",
	"banks_point_7": "\u05D9\u05DB\u05D5\u05DC\u05D9\u05DD \u05DC\u05D7\u05E1\u05D5\u05DD \u05E2\u05E1\u05E7\u05D0\u05D5\u05EA",
