	"point_7_summary_1": "\u05D1\u05D9\u05D8\u05E7\u05D5\u05D9\u05DF \u05E2\u05D5\u05D1\u05D3 24/7 \u05D1\u05E8\u05D7\u05D1\u05D9 \u05D4\u05E2\u05D5\u05DC\u05DD \u05DC\u05DC\u05D0 \u05E9\u05E2\u05D5\u05EA \u05E2\u05E1\u05E7\u05D9\u05DD \u05D0\u05D5 \u05D4\u05D2\u05D1\u05DC\u05D5\u05EA \u05D2\u05D9\u05D0\u05D5\u05D2\u05E8\u05E4\u05D9\u05D5\u05EA.",
